// Multiple package-private classes together for a runnable demo.
package com.bank.txn;

import java.math.BigDecimal;
import java.util.List;
import java.util.logging.*;

public class BankDemo {
    private static final Logger log = Logger.getLogger(BankDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", new BigDecimal("250000"));

        List<Txn> txns = List.of(
            new Deposit(priya, new BigDecimal("20000")),
            new Withdrawal(rajesh, new BigDecimal("5000")),
            new Transfer(rajesh, priya, new BigDecimal("50000"))
        );

        TxnProcessor processor = new TxnProcessor();
        for (Txn t : txns) {
            log.info(() -> "Result: " + processor.describe(t));
        }
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n", r.getMillis(), r.getLevel(), formatMessage(r));
    }
}
