// ─── File: src/main/java/com/bank/txn/TxnProcessor.java ───
package com.bank.txn;

import java.math.BigDecimal;

public class TxnProcessor {

    // Exhaustive switch over the sealed set + record deconstruction patterns.
    // No default branch: the compiler proves all kinds are covered.
    public String describe(Txn txn) {
        return switch (txn) {
            // deconstruct Deposit AND its nested Account record in one pattern
            case Deposit(Account(var id, var bal), var amount) ->
                "DEPOSIT Rs." + amount + " into " + id + " (old bal Rs." + bal + ")";

            case Withdrawal(Account(var id, var bal), var amount) ->
                "WITHDRAW Rs." + amount + " from " + id + " (old bal Rs." + bal + ")";

            // guarded pattern: business rule layered on structural match
            case Transfer(var from, var to, var amount)
                    when amount.compareTo(new BigDecimal("100000")) > 0 ->
                "HIGH-VALUE TRANSFER Rs." + amount + " " + from.id() + "->" + to.id() + " (needs approval)";

            case Transfer(var from, var to, var amount) ->
                "TRANSFER Rs." + amount + " " + from.id() + "->" + to.id();
        };
    }
}
